#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "film_scene_render_binding_candidate.h"
#include "model_skinning_geometry.h"
#include <fstream>
#include <iostream>
#include <set>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);std::ifstream file(R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod\models\anno\mika\mika.mdl)",std::ios::binary);if(!file)throw std::runtime_error("MDL missing");std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});auto bones=readGeometrySkeletonCandidate(bytes);auto attribute=namedAttribute(graph,graph.elements.at(20946),"bones");if(!attribute)throw std::runtime_error("session bones missing");std::set<std::string>savedNames,installedNames;size_t mismatches=0;for(auto&b:bones)installedNames.insert(b.name);for(size_t n=0;n<attribute->values.size();++n){auto&element=graph.elements.at(attribute->values[n].reference);auto label=graph.strings.at(element.name);auto prefix="bone "+std::to_string(n)+" (";if(label.compare(0,prefix.size(),prefix)!=0||label.back()!=')')throw std::runtime_error("bone label schema");auto name=label.substr(prefix.size(),label.size()-prefix.size()-1);if(!savedNames.insert(name).second)throw std::runtime_error("duplicate saved bone name");if(n>=bones.size()||name!=bones[n].name){++mismatches;std::cout<<"index="<<n<<" saved="<<name<<" installed="<<(n<bones.size()?bones[n].name:"<absent>")<<"\n";}}for(auto&name:savedNames)if(!installedNames.count(name))std::cout<<"saved_only="<<name<<"\n";for(auto&name:installedNames)if(!savedNames.count(name))std::cout<<"installed_only="<<name<<"\n";std::cout<<"saved_count="<<savedNames.size()<<" installed_count="<<bones.size()<<" ordered_mismatches="<<mismatches<<" name_sets_equal="<<(savedNames==installedNames)<<" remapping=not_applied\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
